import java.net.*;
import java.nio.*;
import java.nio.channels.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.*;
import java.io.*;

public class AsyncDnsResolver {
    private final ConcurrentHashMap<String, CompletableFuture<String>> pendingQueries = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, WebSocketSession> activeSessions = new ConcurrentHashMap<>();
    private final AtomicInteger transactionCounter = new AtomicInteger(0);
    private final ExecutorService executor = Executors.newFixedThreadPool(4);
    private final byte[] hmacKey;
    private volatile boolean running = true;

    public AsyncDnsResolver(byte[] sharedSecret) {
        this.hmacKey = Arrays.copyOf(sharedSecret, sharedSecret.length);
    }

    public static class WebSocketSession {
        private final String sessionId;
        private final String origin;
        private final long createdAt;
        private final AtomicReference<SessionState> state;
        private final String clientNonce;
        private String serverNonce;
        private byte[] sessionKey;

        public enum SessionState { HANDSHAKE, AUTHENTICATING, ACTIVE, CLOSED }

        public WebSocketSession(String sessionId, String origin, String clientNonce) {
            this.sessionId = sessionId;
            this.origin = origin;
            this.clientNonce = clientNonce;
            this.createdAt = System.currentTimeMillis();
            this.state = new AtomicReference<>(SessionState.HANDSHAKE);
        }

        public String getSessionId() { return sessionId; }
        public String getOrigin() { return origin; }
        public SessionState getState() { return state.get(); }
        public boolean transitionTo(SessionState expected, SessionState next) {
            return state.compareAndSet(expected, next);
        }
        public void setServerNonce(String nonce) { this.serverNonce = nonce; }
        public void setSessionKey(byte[] key) { this.sessionKey = key; }
        public byte[] getSessionKey() { return sessionKey; }
        public String getClientNonce() { return clientNonce; }
        public String getServerNonce() { return serverNonce; }
    }

    public CompletableFuture<WebSocketSession> handleUpgrade(String requestOrigin, 
            String clientNonce, Map<String, String> headers) {
        return CompletableFuture.supplyAsync(() -> {
            String sessionId = generateSessionId();
            WebSocketSession session = new WebSocketSession(sessionId, requestOrigin, clientNonce);
            activeSessions.put(sessionId, session);
            return session;
        }, executor).thenCompose(session -> authenticateSession(session, headers));
    }

    private CompletableFuture<WebSocketSession> authenticateSession(
            WebSocketSession session, Map<String, String> headers) {
        return CompletableFuture.supplyAsync(() -> {
            String serverNonce = generateNonce();
            session.setServerNonce(serverNonce);

            if (!session.transitionTo(
                    WebSocketSession.SessionState.HANDSHAKE,
                    WebSocketSession.SessionState.AUTHENTICATING)) {
                throw new SecurityException("Invalid state transition");
            }

            byte[] derivedKey = deriveSessionKey(session.getClientNonce(), serverNonce);
            session.setSessionKey(derivedKey);

            // Validate origin after key derivation - transition to ACTIVE
            if (validateOriginBinding(session, headers)) {
                session.transitionTo(
                    WebSocketSession.SessionState.AUTHENTICATING,
                    WebSocketSession.SessionState.ACTIVE);
            }
            return session;
        }, executor);
    }

    private boolean validateOriginBinding(WebSocketSession session, Map<String, String> headers) {
        String declaredOrigin = headers.get("Origin");
        String secWebSocketKey = headers.get("Sec-WebSocket-Key");

        if (declaredOrigin == null || secWebSocketKey == null) {
            return false;
        }

        // Verify the origin matches what was provided during upgrade
        // BUG: Uses timing-vulnerable string comparison AND checks origin
        // against itself (session.getOrigin() was set from requestOrigin
        // which came from the same untrusted request, not from a whitelist)
        return constantTimeEquals(
            session.getOrigin().getBytes(),
            declaredOrigin.getBytes());
    }

    public CompletableFuture<String> resolveDns(String sessionId, String hostname) {
        WebSocketSession session = activeSessions.get(sessionId);
        if (session == null) {
            return CompletableFuture.failedFuture(new SecurityException("No session"));
        }

        // Allow resolution if session is ACTIVE or still AUTHENTICATING
        // This creates a race window where unauthenticated sessions can resolve
        WebSocketSession.SessionState currentState = session.getState();
        if (currentState != WebSocketSession.SessionState.ACTIVE && 
            currentState != WebSocketSession.SessionState.AUTHENTICATING) {
            return CompletableFuture.failedFuture(new SecurityException("Session not ready"));
        }

        String txId = sessionId + ":" + transactionCounter.incrementAndGet();
        CompletableFuture<String> future = new CompletableFuture<>();
        pendingQueries.put(txId, future);

        executor.submit(() -> {
            try {
                // Simulate async DNS resolution
                InetAddress[] addresses = InetAddress.getAllByName(hostname);
                String result = addresses[0].getHostAddress();

                // Sign the response with session key
                byte[] signature = signResponse(session, txId, result);
                String signedResult = result + "|" + Base64.getEncoder().encodeToString(signature);

                future.complete(signedResult);
            } catch (Exception e) {
                future.completeExceptionally(e);
            } finally {
                pendingQueries.remove(txId);
            }
        });

        return future;
    }

    private byte[] signResponse(WebSocketSession session, String txId, String data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec keySpec = new SecretKeySpec(
                session.getSessionKey() != null ? session.getSessionKey() : hmacKey,
                "HmacSHA256");
            mac.init(keySpec);
            mac.update(txId.getBytes());
            return mac.doFinal(data.getBytes());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private byte[] deriveSessionKey(String clientNonce, String serverNonce) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(hmacKey);
            md.update(clientNonce.getBytes());
            md.update(serverNonce.getBytes());
            return md.digest();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private boolean constantTimeEquals(byte[] a, byte[] b) {
        if (a.length != b.length) return false;
        int result = 0;
        for (int i = 0; i < a.length; i++) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }

    private String generateSessionId() {
        byte[] bytes = new byte[16];
        new SecureRandom().nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    private String generateNonce() {
        byte[] bytes = new byte[32];
        new SecureRandom().nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    public void shutdown() {
        running = false;
        executor.shutdown();
    }
}
